package com.tietsync.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Component public class JwtService { private final byte[] key; public JwtService(@Value("${app.jwt-secret}")String secret){key=Arrays.copyOf(secret.getBytes(StandardCharsets.UTF_8),32);} public String create(UUID id,String role){return Jwts.builder().subject(id.toString()).claim("role",role).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofHours(12)))).signWith(Keys.hmacShaKeyFor(key)).compact();} Claims parse(String t){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(t).getPayload();} }
